		},
	}
	pg := &legacy.PostgresMock{
		Corpora:   []legacy.LegacyCorpus{{LegacyID: 11, Name: "Docs"}},
		Documents: []legacy.LegacyDocument{{LegacyID: 21, OriginalFilename: "a.pdf", SizeBytes: 100, LegacyCollectionID: 11}},
		Chunks:    map[int64][]legacy.LegacyChunk{21: {{LegacyID: 31, LegacyDocumentID: 21, ChunkIndex: 0, Content: "hi"}}},
		EmbeddingRefs: map[int64][]legacy.LegacyChunkEmbeddingRef{
			21: {{LegacyChunkID: 31, LegacyDocumentID: 21, ChromaID: "p1", VectorCollectionName: "c1"}},
		},
	}

	in := reconcile.Input{
		LegacyMemgraph: memgraph,
		LegacyCorpus:   pg,
		LegacyDocument: pg,
		LegacyChunks:   pg,
		Sidecars: reconcile.Sidecars{
			EntityType:       map[string]string{"legacy:entity-type:1:PERSON": "et-uuid-1"},
			RelationshipType: map[string]string{"legacy:rel-type:1:WORKS_AT": "rt-uuid-1"},
			Corpus:           map[string]string{"legacy:corpus:11": "c-uuid-1"},
			Document:         map[string]string{"legacy:document:21": "d-uuid-1"},
			Chunk:            map[string]string{"legacy:chunk:31": "ch-uuid-1"},
			Entity:           map[string]string{"legacy:entity:101": "e-uuid-1"},
			Edge:             map[string]string{"legacy:edge:201": "ed-uuid-1"},
		},
		Clients: reconcile.Clients{
			EntityType: &fakeEntityType{
				resp: map[string]*entitytypev1.GetResponse{
					"et-uuid-1": {EntityType: &entitytypev1.EntityType{Name: "PERSON"}},
				},
			},
			RelationshipType: &fakeRelType{
				resp: map[string]*relationshiptypev1.GetResponse{
					"rt-uuid-1": {RelationshipType: &relationshiptypev1.RelationshipType{Name: "WORKS_AT"}},
				},
			},
			Corpus: &fakeCorpus{
				resp: map[string]*corpusv1.GetResponse{
					"c-uuid-1": {Corpus: &corpusv1.Corpus{Name: "Docs"}},
				},
			},
			Document: &fakeDocument{
				resp: map[string]*documentv1.GetResponse{
					"d-uuid-1": {Document: &documentv1.Document{Filename: "a.pdf", SizeBytes: 100}},
				},
			},
			Entity: &fakeEntity{
				resp: map[string]*entityv1.GetResponse{
					"e-uuid-1": {Entity: &entityv1.Entity{Label: "Alice"}},
				},
			},
			Edge: &fakeEdge{
				resp: map[string]*edgev1.GetResponse{
					"ed-uuid-1": {Edge: &edgev1.Edge{SourceId: "e-uuid-1", TargetId: "e-uuid-1"}},
				},
			},
		},
		LegacyOrgID: 1,
		OrgID:       "org-uuid",
		SampleSize:  100,
		Rng:         fixedRng(t),
	}

	rep, err := reconcile.Reconcile(context.Background(), in)
	if err != nil {
		t.Fatalf("Reconcile err: %v", err)
	}
	// Embeddings is unreconcilable from the migrator side (no sidecar
	// + no Get RPC) so it always fails parity when legacy > 0. The
	// other 8 phases must all be clean. Subtract that single expected
	// mismatch from the driver total.
	if rep.Mismatches != 1 {
		t.Fatalf("expected exactly 1 mismatch (embeddings unreconcilable), got %d (phases=%+v)", rep.Mismatches, rep.Phases)
	}
	for _, name := range []string{"entity-types", "relationship-types", "corpora", "documents", "chunks", "entities", "edges", "provenance"} {
		pr, ok := rep.Phases[name]
		if !ok {
			t.Fatalf("missing phase %q in report", name)
		}
		if !pr.CountParityOK {
			t.Errorf("phase %q count parity failed: legacy=%d new=%d notes=%v", name, pr.LegacyCount, pr.NewCount, pr.Notes)
		}
		if pr.SampleMismatches != 0 {
			t.Errorf("phase %q has %d mismatches: %v", name, pr.SampleMismatches, pr.Notes)
		}
	}
	if rep.Phases["embeddings"].CountParityOK {
		t.Errorf("embeddings parity should be false when legacy>0 and new=0 (no sidecar)")
	}
	if rep.Phases["embeddings"].LegacyCount != 1 {
		t.Errorf("embeddings legacy_count = %d, want 1", rep.Phases["embeddings"].LegacyCount)
	}
}

