}

// Table-driven sanity for the chunk + embedding sum-from-document_map
// path: ensures iteration over Sidecars.Document drives the legacy
// per-doc reads correctly.
func TestReconcile_ChunksAndEmbeddings_FromDocumentSidecar(t *testing.T) {
	cases := []struct {
		name           string
		chunks         map[int64][]legacy.LegacyChunk
		embRefs        map[int64][]legacy.LegacyChunkEmbeddingRef
		docSidecar     map[string]string
		chunkSidecar   map[string]string
		wantChunkLeg   int
		wantChunkPar   bool
		wantEmbLegacy  int
	}{
		{
			name:         "empty everything",
			docSidecar:   map[string]string{},
			chunkSidecar: map[string]string{},
			wantChunkPar: true,
		},
		{
			name: "two docs sum chunks",
			chunks: map[int64][]legacy.LegacyChunk{
				11: {{LegacyID: 1}, {LegacyID: 2}},
				12: {{LegacyID: 3}},
			},
			embRefs: map[int64][]legacy.LegacyChunkEmbeddingRef{
				11: {{LegacyChunkID: 1}},
			},
			docSidecar: map[string]string{
