func TestReconcile_NoteCap_LimitsAtFive(t *testing.T) {
	// 10 mismatches, but only 5 mismatch notes should be emitted.
	in := baseInput(t)
	in.SampleSize = 100

	legacyTypes := make([]legacy.EntityType, 0, 10)
	sidecar := map[string]string{}
	resp := map[string]*entitytypev1.GetResponse{}
	for i := 0; i < 10; i++ {
		legacyKey := fmt.Sprintf("legacy:entity-type:1:T%d", i)
		newID := fmt.Sprintf("et-%d", i)
		legacyTypes = append(legacyTypes, legacy.EntityType{Name: "OK", LegacyID: legacyKey})
		sidecar[legacyKey] = newID
		// Diverge name on every entry — every sample is a mismatch.
		resp[newID] = &entitytypev1.GetResponse{EntityType: &entitytypev1.EntityType{Name: "BAD"}}
	}
	in.LegacyMemgraph = &legacy.MemgraphMock{EntityTypes: legacyTypes}
	in.Sidecars.EntityType = sidecar
	in.Clients.EntityType = &fakeEntityType{resp: resp}

	rep, err := reconcile.Reconcile(context.Background(), in)
	if err != nil {
		t.Fatalf("Reconcile err: %v", err)
	}
	pr := rep.Phases["entity-types"]
	if pr.SampleMismatches != 10 {
		t.Errorf("expected 10 mismatches, got %d", pr.SampleMismatches)
	}
	if len(pr.Notes) > 5 {
		t.Errorf("note cap exceeded: got %d notes (cap=5)", len(pr.Notes))
	}
}


