			RelationshipType: map[string]string{"legacy:rel-type:1:WORKS_AT": "rt-uuid-1"},
			Corpus:           map[string]string{"legacy:corpus:11": "c-uuid-1"},
			Document:         map[string]string{"legacy:document:21": "d-uuid-1"},
			Chunk:            map[string]string{"legacy:chunk:31": "ch-uuid-1"},
			Entity:           map[string]string{"legacy:entity:101": "e-uuid-1"},
			Edge:             map[string]string{"legacy:edge:201": "ed-uuid-1"},
		},
		Clients: reconcile.Clients{
			EntityType: &fakeEntityType{
				resp: map[string]*entitytypev1.GetResponse{
					"et-uuid-1": {EntityType: &entitytypev1.EntityType{Name: "PERSON"}},
