		}
		if !pr.CountParityOK {
			t.Errorf("phase %q count parity failed: legacy=%d new=%d notes=%v", name, pr.LegacyCount, pr.NewCount, pr.Notes)
		}
		if pr.SampleMismatches != 0 {
			t.Errorf("phase %q has %d mismatches: %v", name, pr.SampleMismatches, pr.Notes)
		}
	}
	if rep.Phases["embeddings"].CountParityOK {
		t.Errorf("embeddings parity should be false when legacy>0 and new=0 (no sidecar)")
	}
	if rep.Phases["embeddings"].LegacyCount != 1 {
		t.Errorf("embeddings legacy_count = %d, want 1", rep.Phases["embeddings"].LegacyCount)
	}
