		}
		if pr.SampleErrors != 0 || pr.SampleMismatches != 0 {
			t.Errorf("phase %q should have zero errors/mismatches on empty: %+v", name, pr)
		}
		if !pr.CountParityOK {
			t.Errorf("phase %q parity should be vacuously OK (0 vs 0)", name)
		}
	}
	if rep.Mismatches != 0 {
		t.Errorf("expected 0 mismatches on all-empty input, got %d", rep.Mismatches)
	}
}

func TestReconcile_NoClients_StillCountsPhase(t *testing.T) {
	// When the client for a phase is nil we must still emit count
	// parity from the sidecar — only deep-spot-check is skipped.
	in := baseInput(t)
	in.LegacyMemgraph = &legacy.MemgraphMock{
		EntityTypes: []legacy.EntityType{
			{Name: "PERSON", LegacyID: "legacy:entity-type:1:PERSON"},
		},
	}
	in.Sidecars.EntityType = map[string]string{
		"legacy:entity-type:1:PERSON": "et-1",
	}
	// No Clients.EntityType wired.
	rep, err := reconcile.Reconcile(context.Background(), in)
	if err != nil {
		t.Fatalf("Reconcile err: %v", err)
	}
	pr := rep.Phases["entity-types"]
	if !pr.CountParityOK {
		t.Errorf("count parity should be OK (1 vs 1)")
	}
	if pr.SampleSize != 0 {
		t.Errorf("SampleSize must be 0 when client unwired, got %d", pr.SampleSize)
	}
	hasSkipNote := false
	for _, n := range pr.Notes {
		if n == "entity-type Get RPC unwired; deep-spot-check skipped" {
			hasSkipNote = true
		}
	}
	if !hasSkipNote {
		t.Errorf("expected skip note, got %v", pr.Notes)
	}
}

