	// both endpoints) and a divergence (new edge points elsewhere).
	in := baseInput(t)
	in.LegacyMemgraph = &legacy.MemgraphMock{
		Edges: []legacy.LegacyEdge{
			{LegacyID: "legacy:edge:201", SourceLegacyID: "legacy:entity:101", TargetLegacyID: "legacy:entity:102", RelationshipType: "WORKS_AT"},
		},
