// Table-driven sanity for the chunk + embedding sum-from-document_map
// path: ensures iteration over Sidecars.Document drives the legacy
// per-doc reads correctly.
func TestReconcile_ChunksAndEmbeddings_FromDocumentSidecar(t *testing.T) {
	cases := []struct {
		name           string
		chunks         map[int64][]legacy.LegacyChunk
		embRefs        map[int64][]legacy.LegacyChunkEmbeddingRef
		docSidecar     map[string]string
		chunkSidecar   map[string]string
		wantChunkLeg   int
		wantChunkPar   bool
		wantEmbLegacy  int
	}{
		{
			name:         "empty everything",
			docSidecar:   map[string]string{},
			chunkSidecar: map[string]string{},
			wantChunkPar: true,
		},
		{
			name: "two docs sum chunks",
			chunks: map[int64][]legacy.LegacyChunk{
				11: {{LegacyID: 1}, {LegacyID: 2}},
				12: {{LegacyID: 3}},
			},
			embRefs: map[int64][]legacy.LegacyChunkEmbeddingRef{
				11: {{LegacyChunkID: 1}},
			},
			docSidecar: map[string]string{
				"legacy:document:11": "d-11",
				"legacy:document:12": "d-12",
			},
			chunkSidecar: map[string]string{
				"legacy:chunk:1": "c-1",
				"legacy:chunk:2": "c-2",
				"legacy:chunk:3": "c-3",
			},
			wantChunkLeg:  3,
			wantChunkPar:  true,
			wantEmbLegacy: 1,
		},
		{
			name: "off-by-one chunks",
			chunks: map[int64][]legacy.LegacyChunk{
				11: {{LegacyID: 1}, {LegacyID: 2}},
			},
			docSidecar: map[string]string{
				"legacy:document:11": "d-11",
			},
			chunkSidecar: map[string]string{
				"legacy:chunk:1": "c-1",
			},
			wantChunkLeg: 2,
			wantChunkPar: false,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			pg := &legacy.PostgresMock{Chunks: tc.chunks, EmbeddingRefs: tc.embRefs}
			in := reconcile.Input{
				LegacyMemgraph: &legacy.MemgraphMock{},
				LegacyCorpus:   pg,
				LegacyDocument: pg,
				LegacyChunks:   pg,
				Sidecars: reconcile.Sidecars{
					Document: tc.docSidecar,
					Chunk:    tc.chunkSidecar,
				},
				LegacyOrgID: 1,
				OrgID:       "org-uuid",
				SampleSize:  10,
				Rng:         fixedRng(t),
			}
			rep, err := reconcile.Reconcile(context.Background(), in)
			if err != nil {
				t.Fatalf("Reconcile err: %v", err)
			}
			pr := rep.Phases["chunks"]
			if pr.LegacyCount != tc.wantChunkLeg {
				t.Errorf("chunk legacy count = %d, want %d", pr.LegacyCount, tc.wantChunkLeg)
			}
			if pr.CountParityOK != tc.wantChunkPar {
				t.Errorf("chunk parity = %v, want %v", pr.CountParityOK, tc.wantChunkPar)
			}
			emb := rep.Phases["embeddings"]
			if emb.LegacyCount != tc.wantEmbLegacy {
				t.Errorf("embedding legacy count = %d, want %d", emb.LegacyCount, tc.wantEmbLegacy)
			}
		})
	}
}



